import type { Hex } from "./contracts";
import { Interface, TypedDataEncoder, getBytes, toBeHex } from "ethers";

import { invisiAddressRegistryAbi } from "./contracts";
import { ReceivingAddress, computeWalletAuthorizationDigest } from "@invisi-labs/core";
import {
    buildRegistrationCalldata,
    createRegistryReceivingKeyLookup,
    registrationAuthorizationRequest,
    registrationPublicInputs,
    registrationTypedData,
} from "@invisi-labs/protocol";
import { describe, expect, it } from "vitest";

// Independently generated by current invisi-protocol address-registry-client and ethers TypedDataEncoder.
const context = {
    chainId: 31337n,
    registryAddress: "0x0000000000000000000000000000000000001234" as const,
};
const registration = {
    walletIdentity: "0x7e5f4552091a69125d5dfcb7b8c2659029395bdf" as const,
    keys: {
        viewingPublicKey:
            "0x02eddb7c79146305faaf1b1d994afc1900e183c5792a128472ac59f41bbf87ad42" as const,
        clueKey: "0xc69480518ea88f8cb925fbcd8f5100b1ebc46cc4d8cbe19e0478936567e6b211" as const,
    },
    nonce: 0n,
    deadline: 2000000000n,
};
const digest = "0xb0ca2d6e049928bee4b33db03c81ffc2169218f9f81cf9b1cc318ec59b22c384";

describe("wallet-authorized receiving-key registry", () => {
    it("matches independent ethers digest, exact seven transcript words, and three public words", () => {
        const request = registrationAuthorizationRequest(context, registration);
        expect(request.operation).toBe("register-address");
        expect(request.capacity).toBe(0);
        expect(request.words).toEqual([
            31337n,
            4660n,
            BigInt(registration.walletIdentity),
            0n,
            2000000000n,
            96006203604636619162062469509936513230n,
            42569196537584161174551333137084101869n,
        ]);
        expect(computeWalletAuthorizationDigest(request)).toBe(digest);
        expect(
            ((typed) =>
                TypedDataEncoder.hash(
                    typed.domain,
                    Object.fromEntries(
                        Object.entries(typed.types).map(([name, fields]) => [
                            name,
                            [...(fields as readonly { name: string; type: string }[])],
                        ])
                    ),
                    typed.message
                ))(registrationTypedData(context, registration))
        ).toBe(digest);
        expect(registrationPublicInputs(context, registration)).toEqual([
            toBeHex(BigInt(registration.walletIdentity), 32),
            "0x00000000000000000000000000000000b0ca2d6e049928bee4b33db03c81ffc2",
            "0x00000000000000000000000000000000169218f9f81cf9b1cc318ec59b22c384",
        ]);
    });
    it("matches the independently generated UpdateAddress nonce-seven vector", () => {
        const updated = { ...registration, nonce: 7n };
        const options = { update: true, expectedNonce: 7n };
        expect(
            computeWalletAuthorizationDigest(
                registrationAuthorizationRequest(context, updated, options)
            )
        ).toBe("0x2a8cf127f7e74135a2ef9431c10c0e49acd58ae6c05c429471202f42de28b850");
        expect(registrationPublicInputs(context, updated, options)).toEqual([
            toBeHex(BigInt(registration.walletIdentity), 32),
            "0x000000000000000000000000000000002a8cf127f7e74135a2ef9431c10c0e49",
            "0x00000000000000000000000000000000acd58ae6c05c429471202f42de28b850",
        ]);
    });
    it("ABI-encodes distinct register/update calls with full identity and no private authorization material", () => {
        for (const update of [false, true]) {
            const request = { ...registration, nonce: update ? 7n : 0n };
            const built = buildRegistrationCalldata(context, request, "0xaabb", {
                update,
                expectedNonce: request.nonce,
            });
            expect(built.to).toBe(context.registryAddress);
            expect(built.value).toBe(0n);
            expect(built.publicInputs).toEqual(
                registrationPublicInputs(context, request, { update })
            );
            const decoded = new Interface(invisiAddressRegistryAbi).parseTransaction({
                data: built.callData,
            })!;
            expect(decoded.name).toBe(update ? "updateKeys" : "registerKeys");
            expect(decoded.args[0].toObject(true)).toEqual({
                ...request,
                walletIdentity: toBeHex(BigInt(request.walletIdentity), 32),
            });
            expect(decoded.args[1]).toBe("0xaabb");
            expect(Object.keys(built).sort()).toEqual(["callData", "publicInputs", "to", "value"]);
        }
    });
    it("binds keys, chain, registry, nonce, deadline, and operation to the authorization digest", () => {
        const changed = [
            registrationAuthorizationRequest({ ...context, chainId: 1n }, registration),
            registrationAuthorizationRequest(
                { ...context, registryAddress: "0x0000000000000000000000000000000000005678" },
                registration
            ),
            registrationAuthorizationRequest(context, {
                ...registration,
                deadline: registration.deadline + 1n,
            }),
            registrationAuthorizationRequest(context, {
                ...registration,
                keys: { ...registration.keys, clueKey: `0x08${"00".repeat(31)}` },
            }),
            registrationAuthorizationRequest(context, {
                ...registration,
                keys: {
                    ...registration.keys,
                    viewingPublicKey: `0x03${registration.keys.viewingPublicKey.slice(4)}`,
                },
            }),
            registrationAuthorizationRequest(context, registration, { update: true }),
            registrationAuthorizationRequest(
                context,
                { ...registration, nonce: 1n },
                { update: true }
            ),
        ];
        for (const request of changed)
            expect(computeWalletAuthorizationDigest(request)).not.toBe(digest);
    });
    it("rejects malformed identities, both point keys, exhausted/mismatched nonces, expiry, and domains", () => {
        for (const walletIdentity of ["0x1234", `0x${"00".repeat(32)}`, `0x${"ff".repeat(32)}`]) {
            expect(() =>
                registrationAuthorizationRequest(context, {
                    ...registration,
                    walletIdentity: walletIdentity as Hex,
                })
            ).toThrow();
        }
        for (const key of ["0x00", `0x04${"00".repeat(32)}`, `0x02${"ff".repeat(32)}`]) {
            expect(() =>
                registrationAuthorizationRequest(context, {
                    ...registration,
                    keys: { ...registration.keys, viewingPublicKey: key as Hex },
                })
            ).toThrow();
        }
        for (const key of [`0x${"00".repeat(32)}`, `0x${"ff".repeat(32)}`, "0x08"]) {
            expect(() =>
                registrationAuthorizationRequest(context, {
                    ...registration,
                    keys: { ...registration.keys, clueKey: key as Hex },
                })
            ).toThrow();
        }
        for (const nonce of [-1n, 1n, (1n << 64n) - 1n, 1n << 64n]) {
            expect(() =>
                registrationAuthorizationRequest(context, { ...registration, nonce })
            ).toThrow();
        }
        expect(() =>
            registrationAuthorizationRequest(
                context,
                { ...registration, nonce: 4n },
                { update: true, expectedNonce: 3n }
            )
        ).toThrow();
        expect(() =>
            registrationAuthorizationRequest(
                { ...context, now: registration.deadline + 1n },
                registration
            )
        ).toThrow();
        expect(() =>
            registrationAuthorizationRequest(
                { ...context, now: registration.deadline },
                registration
            )
        ).not.toThrow();
        for (const chainId of [-1n, 1n << 64n])
            expect(() => registrationTypedData({ ...context, chainId }, registration)).toThrow();
        expect(() =>
            registrationTypedData(
                { ...context, registryAddress: `0x${"00".repeat(20)}` },
                registration
            )
        ).toThrow();
        for (const proof of ["0x", "garbage", "0x1"])
            expect(() => buildRegistrationCalldata(context, registration, proof as Hex)).toThrow();
    });
    it("resolves short and long addresses identically using exactly one receivingKeysOf RPC", async () => {
        let requests = 0;
        const client = {
            provider: null,
            call: async (call: import("ethers").TransactionRequest) => {
                requests++;
                expect(String(call.to).toLowerCase()).toBe(context.registryAddress);
                const iface = new Interface(invisiAddressRegistryAbi);
                expect(iface.parseTransaction({ data: call.data! })!.args[0]).toBe(
                    toBeHex(BigInt(registration.walletIdentity), 32)
                );
                return iface.encodeFunctionResult("receivingKeysOf", [registration.keys, 9n]);
            },
        };
        const lookup = createRegistryReceivingKeyLookup(client, context.registryAddress);
        const receiving = {
            walletIdentity: registration.walletIdentity,
            viewingPublicKey: getBytes(registration.keys.viewingPublicKey),
            clueKey: getBytes(registration.keys.clueKey),
        };
        const long = await ReceivingAddress.parse(
            ReceivingAddress.from(receiving).toString()
        ).resolve(lookup);
        expect(requests).toBe(0);
        expect(
            await ReceivingAddress.parse(
                ReceivingAddress.fromIdentity(registration.walletIdentity).toString()
            ).resolve(lookup)
        ).toEqual(long);
        expect(requests).toBe(1);
    });
    it("propagates lookup RPC failures and rejects returned malformed keys without fallback", async () => {
        const error = new Error("registry unavailable");
        const broken = {
            provider: null,
            call: async () => {
                throw error;
            },
        };
        const lookup = createRegistryReceivingKeyLookup(broken, context.registryAddress);
        await expect(
            ReceivingAddress.parse(
                ReceivingAddress.fromIdentity(registration.walletIdentity).toString()
            ).resolve(lookup)
        ).rejects.toBe(error);
        const malformed = createRegistryReceivingKeyLookup(
            {
                provider: null,
                call: async () =>
                    new Interface(invisiAddressRegistryAbi).encodeFunctionResult(
                        "receivingKeysOf",
                        [{ ...registration.keys, clueKey: `0x${"00".repeat(32)}` }, 1n]
                    ),
            },
            context.registryAddress
        );
        await expect(malformed(registration.walletIdentity)).rejects.toThrow();
    });
});
